const BASE = (() => { try { const _H = ($('[upload] Webhook: POST /upload').first() && $('[upload] Webhook: POST /upload').first().json && $('[upload] Webhook: POST /upload').first().json.headers) || {}; const _h = _H['x-forwarded-host'] || _H.host; if (!_h) return 'http://localhost:5678'; const _p = String(_H['x-forwarded-proto'] || (/localhost|127\.|:5678/.test(_h) ? 'http' : 'https')).split(',')[0].trim(); return _p + '://' + _h; } catch (_) { return 'http://localhost:5678'; } })();
// Принимаем {raw, filename} от адаптеров (Read Text Binary / Extract Docling MD). Парсим markdown-структуру, генерим UUID.
const uuidv4 = () =>
  'xxxxxxxx-xxxx-4xxx-yxxx-xxxxxxxxxxxx'.replace(/[xy]/g, (c) => {
    const r = (Math.random() * 16) | 0;
    const v = c === 'x' ? r : (r & 0x3) | 0x8;
    return v.toString(16);
  });
const src = $input.first().json;
const _hookBody = $('[upload] Webhook: POST /upload').first().json.body || {};
const filename = (src.filename || 'document.txt').normalize('NFC');
// Postgres jsonb отвергает \u0000 и плохо переваривает прочие управляющие — Docling/бинарь могут принести.
let raw = (src.raw || '').normalize('NFC').replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F]/g, '');

const lines = raw.split(/\r?\n/);

// Карта заголовков из ОГЛАВЛЕНИЯ: строки «<номер>. <текст>\t<страница>». Уровень — глубина номера.
const _tocRe = /^(\d+(?:\.\d+)*)\.?\s+(.+?)\s*\t\s*\d+\s*$/;
const _norm = (s) => s.replace(/\*\*/g, '').replace(/\s+/g, ' ').trim().toLowerCase();
const _headMap = new Map();
for (const line of lines) {
  const m = line.match(_tocRe);
  if (m) {
    const _title = m[2].replace(/\*\*/g, '').trim();
    const _level = m[1].split('.').length;
    const _key = _norm(_title);
    if (_key && _key.length >= 3 && !_headMap.has(_key))
      _headMap.set(_key, { level: _level, title: _title });
  }
}

const chapters = [];
let ch = null,
  sec = null,
  buf = [];
const flush = () => {
  const t = buf.join(' ').trim();
  buf = [];
  if (!t) return;
  if (!ch) ch = { title: 'Введение', sections: [] };
  if (!sec) {
    sec = { title: 'Общие положения', paragraphs: [] };
    ch.sections.push(sec);
  }
  sec.paragraphs.push(t);
};
// Строка самого оглавления (заканчивается табом+номером страницы) — мусор, в абзацы не идёт.
const _tocLineRe = /\t\s*\d+\s*$/;
// Уровень заголовка НЕ по числу '#' (Docling даёт ## и для разделов, и для подразделов, без # —
// тогда главы не выделялись), а по: 1) номеру в тексте (## 1 Общие сведения → ур.1; 1.1 → ур.2);
// 2) карте оглавления (по тексту без номера); 3) запасной markdown-глубине (#=глава, иначе секция).
const _numLevel = (s) => {
  const m = String(s).match(/^(\d+(?:\.\d+)*)\.?(?:\s|$)/);
  return m ? m[1].split('.').length : 0;
};
const _stripNum = (s) =>
  String(s)
    .replace(/^(\d+(?:\.\d+)*)\.?\s+/, '')
    .trim();
const _usedHead = new Set();
for (const line of lines) {
  const _t = line.trim();
  let _headText = null,
    _fromToc = false;
  if (/^#{1,6}\s+/.test(line)) {
    _headText = line.replace(/^#{1,6}\s+/, '').trim();
  } else if (_tocLineRe.test(line)) {
    flush();
    continue;
  } else if (_t && _headMap.has(_norm(_t)) && !_usedHead.has(_norm(_t))) {
    _headText = _t;
    _fromToc = true;
  }
  if (_headText !== null && _headText !== '') {
    let _level = _numLevel(_headText);
    if (!_level) {
      const _k = _norm(_stripNum(_headText));
      if (_headMap.has(_k)) _level = _headMap.get(_k).level;
    }
    if (!_level) _level = /^#\s+/.test(line) ? 1 : 2;
    const _title = _stripNum(_headText) || _headText;
    if (_fromToc) _usedHead.add(_norm(_t));
    flush();
    if (_level <= 1) {
      if (ch) chapters.push(ch);
      ch = { title: _title, sections: [] };
      sec = null;
    } else {
      if (!ch) ch = { title: 'Введение', sections: [] };
      sec = { title: _title, paragraphs: [] };
      ch.sections.push(sec);
    }
    continue;
  }
  if (!_t) {
    flush();
    continue;
  }
  buf.push(_t);
}
flush();
if (ch) chapters.push(ch);
if (!chapters.length)
  chapters.push({
    title: filename,
    sections: [{ title: 'Содержимое', paragraphs: [raw.slice(0, 4000) || '(empty)'] }],
  });

const llmText = chapters
  .map((c, ci) =>
    c.sections
      .map(
        (s, si) =>
          '## ' +
          c.title +
          ' → ' +
          s.title +
          '\n' +
          s.paragraphs.map((p, pi) => '[p' + ci + '.' + si + '.' + pi + '] ' + p).join('\n'),
      )
      .join('\n\n'),
  )
  .join('\n\n')
  .slice(0, 12000);

let _pendingModel = 'qwen3:8b';
try {
  const _lc = ($('[upload] Docling Config').first() && $('[upload] Docling Config').first().json) || {};
  const _pp = _lc ? String(_lc.provider || '').toLowerCase() : '';
  if (_lc && _lc.model) _pendingModel = String(_lc.model);
  else if (_pp === 'claude') _pendingModel = 'claude-haiku-4-5';
  else if (_pp === 'develonica') _pendingModel = String('dvl-analyst');
  else if (_pp === 'lmstudio') _pendingModel = String('google/gemma-4-12b');
} catch (_) {}
const _baseName = filename
  .replace(/^[0-9a-f]{8}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{4}-[0-9a-f]{12}_/i, '')
  .replace(/\.[^.]+$/, '');
return [
  {
    json: {
      document_id: _hookBody.document_id || uuidv4(),
      pending_model: _pendingModel,
      job_id: _hookBody.job_id || uuidv4(),
      project_id: _hookBody.project_id || '',
      title:
        !chapters[0] || chapters[0].title === 'Введение'
          ? _baseName
          : chapters[0].title || _baseName,
      filename,
      chapters,
      llm_text: llmText,
      uploaded_by: $('[upload] Auth').first().json._username,
    },
  },
];

// Auth (executeWorkflow) сбрасывает binary с item. Восстанавливаем его из исходного webhook'а
// и одновременно вычисляем _mime_kind, чтобы Route by Mime ниже не дублировал эту логику.
const bin = $('[upload] Webhook: POST /upload').first().binary || {};
const first = Object.values(bin)[0] || {};
const mt = (first.mimeType || '').toLowerCase();
const fn = (first.fileName || '').toLowerCase();
const isText =
  mt.startsWith('text/') || mt === 'application/json' || /\.(txt|md|markdown)$/i.test(fn);
// Адрес Docling — из config Data Table (нода [upload] Docling Config, колонка docling_url),
// в обход $env И без self-HTTP: на «чужих» стендах task-runner — отдельный контейнер, сеть до
// n8n не доходит, а dataTable читается нативно. docling_url можно дать полным URL или только
// хостом — путь /v1/convert/file допишется. Пусто/нет строки → localhost-дефолт.
let _doclingUrl = 'http://localhost:5001/v1/convert/file';
try {
  const _cfg = ($('[upload] Docling Config').first() && $('[upload] Docling Config').first().json) || {};
  let _u = _cfg.docling_url ? String(_cfg.docling_url).trim() : '';
  if (_u) {
    _u = _u.replace(/\/+$/, '');
    if (!/\/convert(\/|$)/.test(_u)) _u = _u + '/v1/convert/file';
    _doclingUrl = _u;
  }
} catch (_) {}
return [
  {
    json: Object.assign({}, $('[upload] Auth').first().json, { _mime_kind: isText ? 'text' : 'binary', _docling_url: _doclingUrl }),
    binary: bin,
  },
];

// Текстовая ветка: webhook отдал text/* (md/txt/markdown). Читаем бинарь через helper
// getBinaryDataBuffer — корректно при ЛЮБОМ N8N_DEFAULT_BINARY_DATA_MODE. В filesystem-режиме
// binary.data — это ССЫЛКА ("filesystem-v2:workflows/.../bin"), а не base64, поэтому старый
// Buffer.from(binary.data,'base64') декодировал строку-ссылку → 9 байт мусора ("~)^...") →
// extract возвращал []. helper читает фактические байты по ссылке (подтверждено diag: len 5759,
// head "## Техническое задание…"). Фолбэк на base64 НЕ ставим — он только маскирует мусором.
// binary доходит сюда из Restore Binary (Encode File и Status: Convert проносят item+binary).
const item = $input.first();
const bmap = (item && item.binary) || {};
const propName = Object.keys(bmap)[0];
let raw = '', filename = 'document.txt', mimeType = 'text/plain';
if (propName) {
  const meta = bmap[propName] || {};
  filename = meta.fileName || filename;
  mimeType = meta.mimeType || mimeType;
  const buf = await this.helpers.getBinaryDataBuffer(0, propName);
  raw = buf.toString('utf-8');
}
return [{ json: { raw, filename, mimeType } }];

// Бинарная ветка: Docling вернул { document: { md_content, filename } } (см. n8n_ivan/AG-DC-AR-01_v1.3).
// Некоторые сборки Docling кладут md в .md/.text/.content — поддерживаем все варианты.
const out = $input.first().json || {};
const doc = out.document || out;
const raw = doc.md_content || doc.md || doc.text || doc.content || '';
const binaryMap = $('[upload] Webhook: POST /upload').first().binary || {};
const firstBin = Object.values(binaryMap)[0] || {};
const filename = doc.filename || firstBin.fileName || 'document';
return [{ json: { raw, filename, mimeType: firstBin.mimeType || 'application/octet-stream' } }];

// Merge LLM output into chapters[].sections[].atomic_requirements[], classify executors, build graph + report, prepare SQL strings.
const src = JSON.parse(JSON.stringify($('[upload] Parse + Generate IDs').first().json));
const chapters = src.chapters;
for (const ch of chapters) for (const s of ch.sections) s.atomic_requirements = [];

// Parse LLM. chainLlm возвращает { text: '...' }; httpRequest к Ollama раньше — { message: { content } }. Поддерживаем оба.
let llmReqs = null;
try {
  const llm = ($('[upload] Merge Chunks').first().json || {}).merged_decompose;
  // chainLlm v1.9 кладёт распарсенный JSON прямо в .json (без text/output-обёртки);
  // fallback на старые формы (text/output/message.content) — для совместимости.
  let parsed = null;
  if (llm && Array.isArray(llm.requirements)) parsed = llm;
  else {
    const content =
      (llm && (llm.text || llm.output)) || (llm && llm.message && llm.message.content);
    if (content) parsed = typeof content === 'string' ? JSON.parse(content) : content;
  }
  if (parsed && Array.isArray(parsed.requirements)) llmReqs = parsed.requirements;
} catch (e) {}
// >>> extracted_requirements parse
// Второй LLM-вызов: документ-уровневый список ФТ/НФТ.
const salvageReqs = (s) => {
  // Вытащить максимум ПОЛНЫХ объектов из (возможно оборванного) JSON: LLM иногда
  // дегенерирует и рвёт массив extracted_requirements на полуслове.
  const out = [];
  const key = s.indexOf('extracted_requirements');
  let i = key >= 0 ? s.indexOf('[', key) : s.indexOf('[');
  if (i < 0) i = 0;
  let depth = 0,
    start = -1,
    inStr = false,
    esc = false;
  for (let k = i; k < s.length; k++) {
    const c = s[k];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') {
      inStr = true;
      continue;
    }
    if (c === '{') {
      if (depth === 0) start = k;
      depth++;
    } else if (c === '}') {
      if (depth > 0) {
        depth--;
        if (depth === 0 && start >= 0) {
          try {
            out.push(JSON.parse(s.slice(start, k + 1)));
          } catch (_) {}
          start = -1;
        }
      }
    }
  }
  return out;
};
let extractedReqs = [];
try {
  const llm2 = ($('[upload] Merge Chunks').first().json || {}).merged_extracted;
  let parsed2 = null;
  if (llm2 && Array.isArray(llm2.extracted_requirements)) parsed2 = llm2;
  else {
    const content2 =
      (llm2 && (llm2.text || llm2.output)) || (llm2 && llm2.message && llm2.message.content);
    if (content2) {
      const s2 = typeof content2 === 'string' ? content2 : JSON.stringify(content2);
      try {
        parsed2 = JSON.parse(s2);
      } catch (e2) {
        parsed2 = { extracted_requirements: salvageReqs(s2) };
      }
    }
  }
  {
    if (parsed2 && Array.isArray(parsed2.extracted_requirements)) {
      extractedReqs = parsed2.extracted_requirements.map((r) => ({
        type: r.type === 'ФТ' || r.type === 'НФТ' ? r.type : 'unknown',
        title: r.title || '',
        statement: r.statement || '',
        fact: r.fact || '',
        risk: r.risk || 'unknown',
        criticality: r.criticality || 'unknown',
        recommendation: r.recommendation || 'unknown',
      }));
    }
  }
} catch (e) {}

// Fallback: LLM Requirements (chainLlm) ненадёжен на больших docs — qwen3 рвёт JSON
// дегенерацией (\n-цикл), chainLlm проглатывает сырьё → extractedReqs пуст. Тогда строим
// Реестр из стабильных атомарных требований Decompose (по абзацу), без ФТ/НФТ-классификации.
if (!extractedReqs.length && Array.isArray(llmReqs)) {
  extractedReqs = llmReqs
    .filter((r) => r && (r.fact || r.recommendation))
    .map((r) => ({
      type: 'unknown',
      title: String(r.fact || '').slice(0, 80),
      statement: String(r.fact || ''),
      fact: String(r.fact || ''),
      risk: r.risk || 'unknown',
      criticality: r.criticality || 'unknown',
    }));
}

// >>> rule-based коррекция ФТ/НФТ поверх LLM-метки. qwen3:8b систематически метит
// функциональные требования как НФТ; корректор асимметричен и консервативен
// (валидирован на Книгах 1/2.2/2.6: НФТ→ФТ — доминирующая правка, ФТ→НФТ — только явные
// атрибуты качества). Не трогает type вне {ФТ,НФТ}. Источник правды — n8n/sql (см. reclassify).
const _FT_VERBS = [
  'должна предоставлять возможность',
  'должна предоставить возможность',
  'предоставляться возможность',
  'возможность',
  'обеспечивать возможность',
  'обеспечить возможность',
  'формир',
  'формиров',
  'создан',
  'создав',
  'создать',
  'созда',
  'редактир',
  'загруж',
  'загруз',
  'выгруж',
  'отображ',
  'отобража',
  'показыва',
  'проверк',
  'проверя',
  'проверить',
  'направл',
  'генерир',
  'генерац',
  'сгенерир',
  'прекрат',
  'прекращ',
  'рассчит',
  'расчёт',
  'расчет',
  'исключ',
  'обновл',
  'обновить',
  'подпис',
  'уведомл',
  'нотификац',
  'учёт',
  'учет',
  'поиск',
  'искать',
  'фильтр',
  'экспорт',
  'импорт',
  'упаков',
  'добав',
  'удал',
  'просмотр',
  'печать',
  'вывести',
  'вывод',
  'заполн',
  'указать',
  'выбор',
  'выбрать',
  'связать',
  'интеграц',
  'синхрониз',
  'отслежив',
  'направлять',
  'хранить',
  'хранен',
  'регистрир',
  'согласован',
  'утвержд',
];
const _STRONG_NFT = [
  'время отклика',
  'производительн',
  'быстродейств',
  'пропускн способн',
  'нагрузочн',
  'под нагрузк',
  'пиковой нагрузк',
  'одновременно работа',
  'одновременных польз',
  'одновременную работу',
  'отказоустойч',
  'доступность систем',
  'доступность сервис',
  'высокая доступн',
  'коэффициент доступн',
  'время простоя',
  'наработк на отказ',
  'круглосуточн',
  '24/7',
  'масштабир',
  'шифрован',
  'удобств использов',
  'интуитивн',
  'юзабилити',
  'эргономи',
  'локализац',
  'язык интерфейс',
  'объём хранен',
  'объем хранен',
  'резервн копир',
  'резервное копир',
  'резервный цод',
  'резервн узел',
  'аварийн переключ',
  'failover',
  'rpo',
  'rto',
  'восстановления из резервн',
  'восстановлен из резервн',
  'переключение на резерв',
];
const _WEAK_NFT = [
  'формат',
  'соответств',
  'совместим',
  'браузер',
  'операционн систем',
  'гост',
  'стандарт',
  'требованиям приказа',
  'требованиям закон',
  'регламент',
  'нормативн',
  'в виде файла',
  'docx',
  'odt',
  'pdf',
];
const _hasKw = (t, a) => a.some((k) => t.includes(k));
const reclassifyType = (r) => {
  const llm = r.type;
  const t = [r.title || '', r.statement || '', r.fact || ''].join(' ').toLowerCase();
  const fT = _hasKw(t, _FT_VERBS),
    sN = _hasKw(t, _STRONG_NFT),
    wN = _hasKw(t, _WEAK_NFT);
  if (llm === 'НФТ') return fT && !sN && !wN ? 'ФТ' : 'НФТ';
  // Нет надёжной ФТ/НФТ-метки (fallback по decompose, когда extract-вызов вернул пусто) —
  // классифицируем С НУЛЯ той же логикой, что и метку ФТ: по умолчанию ФТ, НФТ — только при
  // сильном атрибуте качества без функц. глагола. Реестр больше не пуст при сбое extract.
  return sN && !fT ? 'НФТ' : 'ФТ';
};
for (const _r of extractedReqs) _r.type = reclassifyType(_r);
// <<< rule-based коррекция

const realReqCount = extractedReqs.length;
let _coverageWarn = [];
try {
  const _cov = ($('[upload] Merge Chunks').first().json || {})._coverage;
  if (_cov && _cov.total_paragraphs > 0 && _cov.covered_paragraphs < _cov.total_paragraphs * 0.1)
    _coverageWarn.push(
      'Требования по абзацам извлечены лишь из ' +
        _cov.covered_paragraphs +
        ' из ' +
        _cov.total_paragraphs +
        ' абзацев — проверьте качество декомпозиции',
    );
} catch (_) {}

const placeReq = (ci, si, pi, req) => {
  const ch = chapters[ci];
  if (!ch) return;
  const sec = ch.sections[si];
  if (!sec) return;
  sec.atomic_requirements.push({
    fact: req.fact || '',
    risk: req.risk || 'unknown',
    criticality: req.criticality || 'unknown',
    recommendation: req.recommendation || 'unknown',
    executors: [],
    tracing: { chapter: ch.title, section: sec.title, paragraph_index: pi },
    similar_requirements: [],
    architectural_solutions: [],
    comments: [],
  });
};

// Раскладываем LLM-requirements по абзацам в порядке появления — НЕ доверяя
// LLM-вым индексам chapter_idx/section_idx/paragraph_idx (qwen3:8b часто путает).
// i-й requirement → i-й абзац в документе. Если LLM прислал меньше требований чем
// абзацев — оставшиеся заполняем заглушкой из текста абзаца.
const flatReqs = llmReqs && llmReqs.length ? llmReqs : [];
let flatIdx = 0;
for (let ci = 0; ci < chapters.length; ci++) {
  for (let si = 0; si < chapters[ci].sections.length; si++) {
    const sec = chapters[ci].sections[si];
    for (let pi = 0; pi < sec.paragraphs.length; pi++) {
      const req = flatReqs[flatIdx++];
      if (req && (req.fact || '').trim()) {
        placeReq(ci, si, pi, req);
      } else {
        placeReq(ci, si, pi, {
          fact: sec.paragraphs[pi].slice(0, 200),
          risk: 'unknown',
          criticality: 'unknown',
          recommendation: 'unknown',
        });
      }
    }
  }
}

// Classify executors (rule-based, портированно из agent/classifier.py).
const KW = {
  Аналитик: [
    'требования',
    'анализ',
    'бизнес-процесс',
    'use case',
    'сценарий',
    'спецификация',
    'критерии приемки',
  ],
  Архитектор: [
    'архитектура',
    'компонент',
    'микросервис',
    'интеграция',
    'api',
    'масштабируемость',
    'отказоустойчивость',
  ],
  Разработчик: [
    'код',
    'разработка',
    'реализация',
    'алгоритм',
    'функция',
    'класс',
    'модуль',
    'рефакторинг',
  ],
  Тестировщик: [
    'тест',
    'тестирование',
    'qa',
    'валидация',
    'верификация',
    'баг',
    'test case',
    'покрытие тестами',
  ],
  DevOps: [
    'devops',
    'ci/cd',
    'pipeline',
    'деплой',
    'docker',
    'kubernetes',
    'мониторинг',
    'логирование',
    'terraform',
    'helm',
  ],
};
const classify = (req) => {
  const full = [req.fact, req.risk, req.recommendation].join(' ').toLowerCase();
  const out = new Set();
  for (const [exec, kws] of Object.entries(KW))
    for (const k of kws)
      if (full.includes(k)) {
        out.add(exec);
        break;
      }
  if (!out.size) {
    if (/что|как|почему/.test(full)) out.add('Аналитик');
    else if (/должен|необходимо|требуется/.test(full)) out.add('Архитектор');
    else out.add('Аналитик');
  }
  return [...out];
};
for (const ch of chapters)
  for (const s of ch.sections) for (const r of s.atomic_requirements) r.executors = classify(r);

// Hash — вынесен наверх, потому что нужен ДВАЖДЫ: при сборе RAG payload'ов (paragraph_id для будущих similar_to-рёбер) и при построении графа.
const hash = (s) => {
  let h = 5381;
  const str = String(s);
  for (let i = 0; i < str.length; i++) h = ((h * 33) ^ str.charCodeAt(i)) >>> 0;
  return h.toString(36).padStart(7, '0').slice(0, 12);
};

// RAG chunks: формат '{fact}. Риск: {risk}. Рекомендация: {recommendation}.' — совместим с antisamomatch (см. core.py:556-586).
// paragraph_id записываем в payload чанка — он совпадает с id paragraph-узла графа (см. ниже), и [upload] Enrich Graph использует его чтобы связать local↔external абзацы через similar_to.
// Мусорный абзац: табличная разметка markdown, строка-разделитель, почти без букв или слишком
// короткий. Реальные требования это НЕ затрагивает (фильтруем только заглушки, см. ниже).
const _isJunkPara = (p) => {
  const s = String(p || '')
    .replace(/\*\*/g, '')
    .trim();
  if (s.length < 15) return true;
  if (/^[|+\-\s]+$/.test(s)) return true;
  if ((s.match(/\|/g) || []).length >= 3) return true;
  if ((s.match(/[A-Za-zА-Яа-яЁё]/g) || []).length < 8) return true;
  return false;
};
const _rag_texts = [];
const _rag_payloads = [];
for (let ci = 0; ci < chapters.length; ci++) {
  const _ch = chapters[ci];
  for (let si = 0; si < _ch.sections.length; si++) {
    const _s = _ch.sections[si];
    for (const r of _s.atomic_requirements) {
      const _pi = (r.tracing && r.tracing.paragraph_index) || 0;
      const _p = (_s.paragraphs && _s.paragraphs[_pi]) || '';
      const _pId = 'par_' + hash(_p.slice(0, 50)) + '_' + ci + '_' + si + '_' + _pi;
      const _isStub = String(r.risk) === 'unknown' && String(r.recommendation) === 'unknown';
      // Заглушку по мусорному абзацу (TOC/таблица/разделитель) в Qdrant не пишем.
      if (_isStub && _isJunkPara(_p)) continue;
      // Заглушка → чистый текст абзаца (без «Риск: unknown…»); реальное требование → полный формат.
      const _text = _isStub
        ? String(r.fact || '').trim()
        : r.fact + '. Риск: ' + r.risk + '. Рекомендация: ' + r.recommendation + '.';
      if (!_text) continue;
      _rag_texts.push(_text);
      const _flat = {
        document_id: src.document_id,
        document_title: src.title,
        chapter_title: _ch.title,
        section_title: _s.title,
        content: _text,
        requirement_type: 'atomic',
        executors: r.executors || [],
        risk_level: r.criticality,
        tracing: r.tracing || {},
        paragraph_id: _pId,
      };
      // metadata-mirror для нативного @langchain/qdrant: он читает только payload.content и payload.metadata
      // (см. libs/langchain-qdrant/src/vectorstores). Плоские поля оставляем для Enrich Graph и HTTP-нод.
      const { content: _c, ..._meta } = _flat;
      _rag_payloads.push(Object.assign({}, _flat, { metadata: _meta }));
    }
  }
}

// Build graph + paragraphs + report.
const nodes = [],
  edges = [],
  paragraphs = [];
let totalReqs = 0;
const docNodeId = 'doc_' + hash(src.title);
nodes.push({ id: docNodeId, type: 'document', label: src.title, data: { filename: src.filename } });
for (let ci = 0; ci < chapters.length; ci++) {
  const ch = chapters[ci];
  const chId = 'chap_' + hash(ch.title) + '_' + ci;
  nodes.push({ id: chId, type: 'chapter', label: ch.title, data: { idx: ci } });
  edges.push({
    id: 'e_' + docNodeId + '_' + chId,
    source: docNodeId,
    target: chId,
    type: 'contains',
  });
  for (let si = 0; si < ch.sections.length; si++) {
    const sec = ch.sections[si];
    const secId = 'sec_' + hash(sec.title) + '_' + ci + '_' + si;
    nodes.push({ id: secId, type: 'section', label: sec.title, data: { idx: si } });
    edges.push({ id: 'e_' + chId + '_' + secId, source: chId, target: secId, type: 'contains' });
    for (let pi = 0; pi < sec.paragraphs.length; pi++) {
      const p = sec.paragraphs[pi];
      const pId = 'par_' + hash(p.slice(0, 50)) + '_' + ci + '_' + si + '_' + pi;
      nodes.push({ id: pId, type: 'paragraph', label: p.slice(0, 80), data: { text: p, idx: pi } });
      edges.push({ id: 'e_' + secId + '_' + pId, source: secId, target: pId, type: 'contains' });
      const reqs = sec.atomic_requirements.filter(
        (r) => (r.tracing && r.tracing.paragraph_index) === pi,
      );
      totalReqs += reqs.length;
      paragraphs.push({
        paragraph_index: paragraphs.length,
        chapter: ch.title,
        section: sec.title,
        text: p,
        requirements: reqs,
      });
      // Бэкфил paragraph_global_index в _rag_payloads — Enrich Graph ниже прицепит similar_requirements к конкретному paragraph по этому индексу.
      const _gpi = paragraphs.length - 1;
      for (const _rp of _rag_payloads) {
        if (_rp.paragraph_id === pId && _rp.paragraph_global_index === undefined) {
          _rp.paragraph_global_index = _gpi;
          if (_rp.metadata) _rp.metadata.paragraph_global_index = _gpi;
        }
      }
    }
  }
}
const stats = {
  total_nodes: nodes.length,
  total_edges: edges.length,
  paragraphs: nodes.filter((n) => n.type === 'paragraph').length,
  chunks: 0,
  intersections: 0,
  external_docs: 0,
};

const lines = [];
lines.push('# Отчёт по анализу документа: ' + src.title + '\n');
lines.push('**Файл:** ' + src.filename + '\n');
lines.push('**Всего глав:** ' + chapters.length + '\n');
lines.push('**Всего требований (ФТ/НФТ):** ' + realReqCount + '\n');
lines.push('---\n');
for (let ci = 0; ci < chapters.length; ci++) {
  const ch = chapters[ci];
  lines.push('# ' + (ci + 1) + '. ' + ch.title + '\n');
  for (let si = 0; si < ch.sections.length; si++) {
    const s = ch.sections[si];
    lines.push('## ' + (ci + 1) + '.' + (si + 1) + ' ' + s.title + '\n');
    for (const r of s.atomic_requirements) {
      const p = ((r.tracing && r.tracing.paragraph_index) || 0) + 1;
      lines.push('**Абзац #' + p + '**\n');
      lines.push('* Факт: ' + r.fact);
      lines.push('* Риск: ' + r.risk);
      lines.push('* Критичность: ' + r.criticality);
      lines.push('* Рекомендация: ' + r.recommendation);
      lines.push('* Исполнители: ' + (r.executors || []).join(', '));
      lines.push('');
    }
  }
}
const report = lines.join('\n');
const graph = { nodes, edges, stats };
graph.llm = ($('[upload] Merge Chunks').first().json || {})._llm_usage || null;
const payload = { graph, paragraphs, extracted_requirements: extractedReqs };
const now = new Date().toISOString();

// Статус документа: при недообработанных фрагментах (LLM не ответил даже после retry) — 'partial',
// чтобы История показала проблему и кнопку «Возобновить», а не ложное «Готово». Возобновление
// добивает недостающие чанки (чекпойнт job_chunks), и при failed=0 статус станет 'completed'.
let _chunkStats = null;
try {
  _chunkStats = ($('[upload] Merge Chunks').first().json || {})._chunk_stats || null;
} catch (_) {}
const _failedChunks = (_chunkStats && Number(_chunkStats.failed)) || 0;
let _wasCancelled = false;
try {
  _wasCancelled = !!($('[upload] Merge Chunks').first().json || {})._cancelled;
} catch (_) {}
const _docStatus = _failedChunks > 0 ? 'partial' : 'completed';
const _errList = [];
if (_failedChunks > 0) {
  if (_wasCancelled)
    _errList.push(
      'Обработка отменена пользователем: готово ' +
        (_chunkStats.total - _failedChunks) +
        ' из ' +
        _chunkStats.total +
        ' фрагментов. Возобновите, чтобы добрать остальные.',
    );
  else
    _errList.push(
      'Не обработано ' +
        _failedChunks +
        ' из ' +
        _chunkStats.total +
        ' фрагментов: LLM не ответил после повторных попыток. Возобновите обработку, чтобы добрать недостающие.',
    );
}

// Прикладные данные ушли из Postgres в n8n Data Tables. Заранее лепим три row-объекта под колонки
// users/uploads/jobs/graphs (см. n8n/sql/data_tables_bootstrap.mjs). JSON-поля сериализуем в строку —
// в Data Tables нет JSONB-типа, есть только string/number/boolean/date.
const _upload_row = {
  // `id` зарезервировано Data Tables (auto-number) — наш UUID документа храним в upload_id.
  upload_id: src.document_id,
  filename: src.filename,
  storage_key: 'n8n://' + src.document_id,
  uploaded_by: src.uploaded_by,
  uploaded_at: now,
