const _job_row = {
  job_id: src.job_id,
  document_id: src.document_id,
  title: src.title,
  report: report,
  total_requirements: realReqCount,
  errors_json: JSON.stringify(_errList),
  warnings_json: JSON.stringify(_coverageWarn),
  payload_json: JSON.stringify(payload),
  created_at: now,
};

const _graph_row = {
  document_id: src.document_id,
  title: src.title,
  filename: src.filename,
  total_requirements: realReqCount,
  graph_json: JSON.stringify(graph),
  paragraphs_json: JSON.stringify(paragraphs),
  saved_at: now,
  status: _docStatus,
  job_id: src.job_id,
  model: ($('[upload] Merge Chunks').first().json || {})._llm_model || '',
};

return [
  {
    json: {
      document_id: src.document_id,
      job_id: src.job_id,
      title: src.title,
      filename: src.filename,
      total_requirements: realReqCount,
      _upload_row: _upload_row,
      _job_row: _job_row,
      _graph_row: _graph_row,
      _rag_texts: _rag_texts,
      _rag_payloads: _rag_payloads,
    },
  },
];

// На основе результатов Qdrant /points/search/batch:
//   * добавляем similar_to-рёбра между local paragraph-узлами текущего документа и paragraph-узлами других документов
//   * добавляем external_paragraph-узлы (чтобы граф был замкнут) — кладём в graph.nodes
//   * заполняем paragraphs[].requirements[].similar_requirements
//   * пересчитываем stats.intersections / stats.external_docs
// Из Build Everything подтягиваем base-output, переписываем _job_row.payload_json и _graph_row.{graph_json,paragraphs_json} обогащёнными данными.
const be = $('[upload] Build Everything').first().json;
const ragPayloads = be._rag_payloads || [];
const docId = be.document_id;

let graph = { nodes: [], edges: [], stats: {} };
let paragraphs = [];
let extractedReqs = [];
try {
  const _p = JSON.parse(be._job_row.payload_json);
  graph = _p.graph || graph;
  paragraphs = _p.paragraphs || [];
  extractedReqs = Array.isArray(_p.extracted_requirements) ? _p.extracted_requirements : [];
} catch (_) {}

const searchInput = ($input.first() && $input.first().json) || {};
const searchResult = Array.isArray(searchInput.result) ? searchInput.result : [];

const nodeIds = new Set(graph.nodes.map((n) => n.id));
// paragraph_id генерируется детерминированно из текста абзаца → старые чанки с тем же текстом
// дадут тот же extPId, что и наш local. Чтобы не плодить self-loop'ов, заранее знаем свои.
const localParagraphIds = new Set(ragPayloads.map((p) => p.paragraph_id));
const externalDocs = new Set();
let intersections = 0;

for (let i = 0; i < ragPayloads.length; i++) {
  const localPayload = ragPayloads[i] || {};
  const localPId = localPayload.paragraph_id;
  const localGI = localPayload.paragraph_global_index;
  const hits = searchResult[i] || [];
  for (const hit of hits) {
    const pl = hit.payload || {};
    const extDocId = pl.document_id;
    const extPId = pl.paragraph_id;
    if (!extDocId || extDocId === docId) continue;
    if (!extPId) continue;
    if (localParagraphIds.has(extPId)) continue;
    if (!nodeIds.has(extPId)) {
      // Контракт фронта (frontend/src/types/index.ts::GraphNode): type='external', content=<text>, metadata.source_document, metadata.document_id, level=4.
      graph.nodes.push({
        id: extPId,
        type: 'external',
        label: (pl.document_title || '?') + ': ' + String(pl.content || '').slice(0, 60),
        content: pl.content || '',
        metadata: {
          document_id: extDocId,
          source_document: pl.document_title || '',
          score: hit.score,
        },
        level: 4,
      });
      nodeIds.add(extPId);
    }
    // Контракт фронта (GraphEdge): между документами — type='intersects', weight=score (number; фронт делает weight.toFixed(2) и упадёт если undefined).
    graph.edges.push({
      id: 'e_sim_' + localPId + '_' + extPId,
      source: localPId,
      target: extPId,
      type: 'intersects',
      weight: hit.score,
    });
    intersections++;
    externalDocs.add(extDocId);
    if (typeof localGI === 'number' && paragraphs[localGI]) {
      const reqs = paragraphs[localGI].requirements || [];
      for (const r of reqs) {
        if (!Array.isArray(r.similar_requirements)) r.similar_requirements = [];
        // Контракт фронта (ParagraphRow.similar_requirements): {id, score, content, document_id?, source_document?}.
        r.similar_requirements.push({
          id: extPId,
          score: hit.score,
          content: pl.content || '',
          document_id: extDocId,
          source_document: pl.document_title || '',
        });
      }
    }
  }
}

graph.stats = Object.assign({}, graph.stats, {
  total_nodes: graph.nodes.length,
  total_edges: graph.edges.length,
  intersections: intersections,
  external_docs: externalDocs.size,
});

const payload = { graph, paragraphs, extracted_requirements: extractedReqs };
const newJobRow = Object.assign({}, be._job_row, { payload_json: JSON.stringify(payload) });
const newGraphRow = Object.assign({}, be._graph_row, {
  graph_json: JSON.stringify(graph),
  paragraphs_json: JSON.stringify(paragraphs),
});

return [{ json: Object.assign({}, be, { _job_row: newJobRow, _graph_row: newGraphRow }) }];

const BASE = (() => { try { const _H = ($('[upload] Webhook: POST /upload').first() && $('[upload] Webhook: POST /upload').first().json && $('[upload] Webhook: POST /upload').first().json.headers) || {}; const _h = _H['x-forwarded-host'] || _H.host; if (!_h) return 'http://localhost:5678'; const _p = String(_H['x-forwarded-proto'] || (/localhost|127\.|:5678/.test(_h) ? 'http' : 'https')).split(',')[0].trim(); return _p + '://' + _h; } catch (_) { return 'http://localhost:5678'; } })();
