const BASE = (() => { try { const _H = ($('[upload] Webhook: POST /upload').first() && $('[upload] Webhook: POST /upload').first().json && $('[upload] Webhook: POST /upload').first().json.headers) || {}; const _h = _H['x-forwarded-host'] || _H.host; if (!_h) return 'http://localhost:5678'; const _p = String(_H['x-forwarded-proto'] || (/localhost|127\.|:5678/.test(_h) ? 'http' : 'https')).split(',')[0].trim(); return _p + '://' + _h; } catch (_) { return 'http://localhost:5678'; } })();
const jobId = $('[upload] Webhook: POST /upload').first().json.body.job_id;
try {
