const BASE = (() => { try { const _H = ($('[jobStatus] Webhook: GET /jobs/status').first() && $('[jobStatus] Webhook: GET /jobs/status').first().json && $('[jobStatus] Webhook: GET /jobs/status').first().json.headers) || {}; const _h = _H['x-forwarded-host'] || _H.host; if (!_h) return 'http://localhost:5678'; const _p = String(_H['x-forwarded-proto'] || (/localhost|127\.|:5678/.test(_h) ? 'http' : 'https')).split(',')[0].trim(); return _p + '://' + _h; } catch (_) { return 'http://localhost:5678'; } })();
// Строка job_status -> {stage, percent}. Нет строки = обработка ещё не дошла до первого этапа.
const row = $input.first()?.json;
// Живой счётчик извлечённых ФТ/НФТ: суммируем по уже сохранённым чанкам (job_chunks пишется по ходу
// воркером Merge Chunks). Так число «требований» растёт во время обработки, не дожидаясь финала.
// Считаем только extract-ветку (o.e.extracted_requirements) — это и есть будущий total_requirements.
let requirements = 0;
try {
  const jobId = $('[jobStatus] Webhook: GET /jobs/status').first().json.query.job_id || '';
  if (jobId) {
    const rr = await this.helpers.httpRequest({
      method: 'GET',
      url: BASE + '/webhook/chunk-list',
      qs: { job_id: jobId },
      json: true,
      timeout: 8000,
    });
    for (const c of (rr && rr.chunks) || []) {
      if (!c || c.chunk_index === undefined || Number(c.chunk_index) < 0 || c.output === undefined)
        continue;
      let e = '';
      try {
        const o = JSON.parse(String(c.output || ''));
        e = o && typeof o.e === 'string' ? o.e : '';
      } catch (_) {}
      if (!e) continue;
      try {
        const ej = JSON.parse(e);
        if (Array.isArray(ej.extracted_requirements))
          requirements += ej.extracted_requirements.length;
      } catch (_) {
        const m = e.match(/"type"\s*:/g);
        if (m) requirements += m.length;
      }
    }
  }
} catch (_) {}
if (!row || row.percent === undefined) {
  return [{ json: { _http_code: 200, _body: { stage: 'В очереди', percent: 0, requirements } } }];
}
return [
  {
    json: {
      _http_code: 200,
      _body: {
        stage: row.stage || '',
        percent: Number(row.percent) || 0,
        updated_at: row.updated_at || '',
        requirements,
      },
    },
  },
];

// jobs.payload_json — JSON-строка {graph, paragraphs}. Достаём graph.
const row = $input.first()?.json;
if (!row || !row.payload_json) {
  return [{ json: { _http_code: 404, _body: { detail: 'Job not found' } } }];
}
let p = {};
try {
  p = JSON.parse(row.payload_json);
} catch (_) {}
const g = (p && p.graph) || {};
return [
  {
