// Чистая логика чанкинга и сборки — тестируется офлайн, затем встраивается в ноды
// [upload] Build Chunks и [upload] Merge Chunks один-в-один (см. patch_wf.mjs).
// НИКАКИХ n8n-глобалов здесь: только обычные функции над plain-объектами.

function buildChunks(chapters, opts) {
  const maxParas = (opts && opts.maxParas) || 18;
  const maxChars = (opts && opts.maxChars) || 7000;

  // Плоский список абзацев со СКВОЗНЫМ gi в ТОЧНО ТОМ ЖЕ порядке обхода,
  // что и [upload] Build Everything (for ci -> for si -> for pi). gi === flatIdx там.
  const flat = [];
  let gi = 0;
  for (let ci = 0; ci < chapters.length; ci++) {
    const ch = chapters[ci];
    for (let si = 0; si < ch.sections.length; si++) {
      const sec = ch.sections[si];
      for (let pi = 0; pi < sec.paragraphs.length; pi++) {
        flat.push({
          ci,
          si,
          pi,
          gi: gi++,
          text: String(sec.paragraphs[pi] || ''),
          chTitle: ch.title,
          secTitle: sec.title,
        });
      }
    }
  }
  const total = flat.length;

  // Группируем подряд идущие абзацы одной секции.
  const sections = [];
  for (const d of flat) {
    const last = sections[sections.length - 1];
    if (last && last.ci === d.ci && last.si === d.si) last.paras.push(d);
    else sections.push({ ci: d.ci, si: d.si, paras: [d] });
  }

  const charsOf = (arr) => arr.reduce((a, d) => a + d.text.length, 0);
  const chunks = [];
  let cur = null;
  const flush = () => {
    if (cur && cur.length) chunks.push(cur);
    cur = null;
  };

  for (const sec of sections) {
    if (sec.paras.length > maxParas || charsOf(sec.paras) > maxChars) {
      // Секция крупнее лимита — добиваем по абзацам в отдельные чанки.
      flush();
      let sub = [],
        subChars = 0;
      for (const d of sec.paras) {
        if (sub.length >= maxParas || (subChars + d.text.length > maxChars && sub.length)) {
          chunks.push(sub);
          sub = [];
          subChars = 0;
        }
        sub.push(d);
        subChars += d.text.length;
      }
      if (sub.length) chunks.push(sub);
    } else {
      // Мелкие секции упаковываем вместе, пока влезает.
      if (
        cur &&
        (cur.length + sec.paras.length > maxParas || charsOf(cur) + charsOf(sec.paras) > maxChars)
      )
        flush();
      if (!cur) cur = [];
      for (const d of sec.paras) cur.push(d);
    }
  }
  flush();

  return chunks.map((paras, idx) => {
    const lines = [];
    let curKey = null;
    for (const d of paras) {
      const key = d.ci + '.' + d.si;
      if (key !== curKey) {
        lines.push('## ' + d.chTitle + ' → ' + d.secTitle);
        curKey = key;
      }
      lines.push('[p' + d.ci + '.' + d.si + '.' + d.pi + '] ' + d.text);
    }
    return {
      chunk_index: idx,
      chunk_total: chunks.length,
      total_paragraphs: total,
      chunk_paragraphs: paras.map((d) => ({
        ci: d.ci,
        si: d.si,
        pi: d.pi,
        gi: d.gi,
        text: d.text,
      })),
      chunk_text: lines.join('\n'),
    };
  });
}

// Балансным разбором достаём максимум ПОЛНЫХ {} из (возможно оборванного) JSON
// внутри массива по ключу key. Порт из Build Everything.salvageReqs, обобщён на key.
function salvageObjects(s, key) {
  const out = [];
  const ki = key ? s.indexOf(key) : -1;
  let i = ki >= 0 ? s.indexOf('[', ki) : s.indexOf('[');
  if (i < 0) i = 0;
  let depth = 0,
    start = -1,
    inStr = false,
    esc = false;
  for (let k = i; k < s.length; k++) {
    const c = s[k];
    if (inStr) {
      if (esc) esc = false;
      else if (c === '\\') esc = true;
      else if (c === '"') inStr = false;
      continue;
    }
    if (c === '"') {
      inStr = true;
      continue;
    }
    if (c === '{') {
      if (depth === 0) start = k;
      depth++;
    } else if (c === '}') {
      if (depth > 0) {
        depth--;
        if (depth === 0 && start >= 0) {
          try {
            out.push(JSON.parse(s.slice(start, k + 1)));
          } catch (_) {}
          start = -1;
        }
      }
    }
  }
  return out;
}

// chainLlm v1.9 кладёт распарсенный JSON прямо в .json; fallback на text/output/message.content;
// если строка оборвана дегенерацией — salvage по обоим ключам.
function parseChunkOutput(o) {
  if (!o) return {};
  if (Array.isArray(o.requirements) || Array.isArray(o.extracted_requirements)) return o;
  const content = o.text || o.output || (o.message && o.message.content);
  if (!content) return {};
  if (typeof content !== 'string') return content;
  try {
    return JSON.parse(content);
  } catch (_) {
    return {
      requirements: salvageObjects(content, 'requirements'),
      extracted_requirements: salvageObjects(content, 'extracted_requirements'),
    };
  }
}

// Склейка выходов чанков обратно в документ-уровневые структуры, которые ждёт Build Everything:
//   merged_decompose.requirements — ПЛОТНЫЙ массив длиной = всего абзацев, в порядке gi (== порядок Build Everything)
//   merged_extracted.extracted_requirements — конкатенация ФТ/НФТ всех чанков
function mergeChunks(chunkDescriptors, llmOutputs, chapters) {
  // totalParas считаем по chapters — это гарантирует выравнивание с циклом Build Everything.
  let totalParas = 0;
  for (const ch of chapters) for (const sec of ch.sections) totalParas += sec.paragraphs.length;

  const dense = new Array(totalParas).fill(null);
  const extracted = [];
  let covered = 0;

  // llmOutputs[k] = { d: <decompose JSON-строка>, e: <extract JSON-строка> }.
  for (let k = 0; k < chunkDescriptors.length; k++) {
    const cps = (chunkDescriptors[k] && chunkDescriptors[k].chunk_paragraphs) || [];
    const o = llmOutputs[k] || {};
    // decompose сопоставляем по ref-метке [pCI.SI.PI] -> gi (надёжнее позиционного: модель
    // пропускает несодержательные абзацы — заголовки/оглавление — без сдвига остальных).
    const refMap = {};
    for (const c of cps) refMap[c.ci + '.' + c.si + '.' + c.pi] = c.gi;
    const dec = parseChunkOutput({ text: o.d });
    const dreqs = Array.isArray(dec.requirements) ? dec.requirements : [];
    for (const r of dreqs) {
      if (!r || !String(r.fact || '').trim()) continue;
      const key = String(r.ref || '').replace(/[^\d.]/g, '');
      const gi = refMap[key];
      if (gi !== undefined && gi >= 0 && gi < totalParas && dense[gi] === null) {
        dense[gi] = r;
        covered++;
      }
    }
    const ext = parseChunkOutput({ text: o.e });
    const exs = Array.isArray(ext.extracted_requirements) ? ext.extracted_requirements : [];
    for (const e of exs) if (e) extracted.push(e);
  }

  return {
    merged_decompose: { requirements: dense.map((r) => r || { fact: '' }) },
    merged_extracted: { extracted_requirements: extracted },
    _coverage: {
      total_paragraphs: totalParas,
      covered_paragraphs: covered,
      chunks: chunkDescriptors.length,
    },
  };
}

