// Склейка выходов чанков обратно в документ-уровневые структуры, которые ждёт Build Everything:
//   merged_decompose.requirements — ПЛОТНЫЙ массив длиной = всего абзацев, в порядке gi (== порядок Build Everything)
//   merged_extracted.extracted_requirements — конкатенация ФТ/НФТ всех чанков
function mergeChunks(chunkDescriptors, llmOutputs, chapters) {
  // totalParas считаем по chapters — это гарантирует выравнивание с циклом Build Everything.
  let totalParas = 0;
  for (const ch of chapters) for (const sec of ch.sections) totalParas += sec.paragraphs.length;

  const dense = new Array(totalParas).fill(null);
  const extracted = [];
  let covered = 0;

  // llmOutputs[k] = { d: <decompose JSON-строка>, e: <extract JSON-строка> }.
  for (let k = 0; k < chunkDescriptors.length; k++) {
    const cps = (chunkDescriptors[k] && chunkDescriptors[k].chunk_paragraphs) || [];
    const o = llmOutputs[k] || {};
