    // пропускает несодержательные абзацы — заголовки/оглавление — без сдвига остальных).
    const refMap = {};
    for (const c of cps) refMap[c.ci + '.' + c.si + '.' + c.pi] = c.gi;
    const dec = parseChunkOutput({ text: o.d });
    const dreqs = Array.isArray(dec.requirements) ? dec.requirements : [];
    for (const r of dreqs) {
      if (!r || !String(r.fact || '').trim()) continue;
      const key = String(r.ref || '').replace(/[^\d.]/g, '');
      const gi = refMap[key];
      if (gi !== undefined && gi >= 0 && gi < totalParas && dense[gi] === null) {
        dense[gi] = r;
        covered++;
      }
    }
    const ext = parseChunkOutput({ text: o.e });
    const exs = Array.isArray(ext.extracted_requirements) ? ext.extracted_requirements : [];
    for (const e of exs) if (e) extracted.push(e);
  }

  return {
    merged_decompose: { requirements: dense.map((r) => r || { fact: '' }) },
    merged_extracted: { extracted_requirements: extracted },
    _coverage: {
      total_paragraphs: totalParas,
      covered_paragraphs: covered,
      chunks: chunkDescriptors.length,
    },
  };
}

